CREATE TABLE "SaleCart" ("id" TEXT NOT NULL, "organizationId" TEXT NOT NULL, "shopId" TEXT NOT NULL, "status" VARCHAR(16) NOT NULL DEFAULT 'DRAFT', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "SaleCart_pkey" PRIMARY KEY ("id"));
CREATE TABLE "SaleLine" ("id" TEXT NOT NULL, "saleCartId" TEXT NOT NULL, "productId" TEXT NOT NULL, "productNameSnapshot" TEXT NOT NULL, "quantity" DECIMAL(18,3) NOT NULL, "unitPriceMinor" BIGINT NOT NULL, "unitCostMinor" BIGINT NOT NULL, "currency" VARCHAR(3) NOT NULL, "discountMinor" BIGINT NOT NULL DEFAULT 0, CONSTRAINT "SaleLine_pkey" PRIMARY KEY ("id"));
CREATE INDEX "SaleCart_organizationId_shopId_status_idx" ON "SaleCart"("organizationId","shopId","status"); CREATE INDEX "SaleLine_saleCartId_idx" ON "SaleLine"("saleCartId");
ALTER TABLE "SaleCart" ADD CONSTRAINT "SaleCart_organizationId_fkey" FOREIGN KEY ("organizationId") REFERENCES "Organization"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "SaleCart" ADD CONSTRAINT "SaleCart_shopId_fkey" FOREIGN KEY ("shopId") REFERENCES "Shop"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "SaleLine" ADD CONSTRAINT "SaleLine_saleCartId_fkey" FOREIGN KEY ("saleCartId") REFERENCES "SaleCart"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "SaleLine" ADD CONSTRAINT "SaleLine_productId_fkey" FOREIGN KEY ("productId") REFERENCES "Product"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
